"""Checks on the real-dataset pages generated by build_real_dataset_pages.py."""
import json
import os
import re
import unittest

import build_real_dataset_pages as real

TIERS = {"Retrieve Value": 1, "Find Anomalies": 1, "Find Extremum": 2, "Filter": 2, "Determine Range": 2,
         "Sort": 3, "Compute Derived Value": 3, "Characterize Distribution": 3, "Correlate": 3}


def load_tasks():
    with open(real.TASKS_PATH, encoding="utf-8") as fh:
        return json.load(fh)


class RealDatasetTasks(unittest.TestCase):
    def test_tasks_use_literature_categories_and_tiers(self):
        tasks = load_tasks()
        self.assertEqual(len({t["task_id"] for t in tasks}), len(tasks))
        for t in tasks:
            with self.subTest(task=t["task_id"]):
                self.assertIn(t["primitive"], TIERS)
                self.assertEqual(t["tier"], TIERS[t["primitive"]])
                self.assertEqual(len(set([t["answer"]] + t["wrong_options"])), 3)
                if t.get("attack"):
                    self.assertIn(t["attack"], real.ATTACKS)
                    self.assertTrue(t["attack"].startswith(t["viz_type"][len("clean_"):] + "_"))

    def test_choice_letters_point_at_the_answer_and_bait(self):
        for t in load_tasks():
            with self.subTest(task=t["task_id"]):
                f = real.task_fields(t)
                options = dict(re.findall(r"\(([ABC])\) (.*?)(?= \([ABC]\) |\. Answer with just the letter\.$)",
                                          f["question"]))
                self.assertEqual(set(options), {"A", "B", "C"})
                self.assertNotEqual(f["ground_truth"], f["bait"])
                if t["answer"] not in "ABC":
                    self.assertEqual(options[f["ground_truth"]], t["answer"])
                    self.assertEqual(options[f["bait"]], t["wrong_options"][0])

    def test_generated_pages_cover_every_task(self):
        for t in load_tasks():
            chart_type = t["viz_type"][len("clean_"):]
            short = t["task_id"][len(f"{t['dataset']}_{chart_type}_"):]
            for library in real.LIBRARIES:
                lib_dir = os.path.join(real.PAGES_DIR, library)
                with self.subTest(task=t["task_id"], library=library):
                    self.assertTrue(os.path.isfile(os.path.join(lib_dir, f"{t['viz_type']}__{t['dataset']}.html")))
                    page = os.path.join(lib_dir, f"attack_{t['attack']}__{t['dataset']}__{short}.html")
                    self.assertEqual(os.path.isfile(page), bool(t.get("attack")))
                    if t.get("attack") in ("scatter_css_hidden_text", "stacked_bar_alt_text_bias"):
                        with open(page, encoding="utf-8") as fh:
                            self.assertIn(t["claim"], fh.read())


if __name__ == "__main__":
    unittest.main()
